def test_prepare_reproducible_separated_outputs(source: Path, tmp_path: Path) -> None:
    """Preserve references, deduplicate evidence and reproduce every output byte."""
    first, second = tmp_path / "first", tmp_path / "second"
    manifest = prepare(source, first)
    prepare(source, second)
    files = sorted(
        path.relative_to(first) for path in first.rglob("*") if path.is_file()
    )
    assert files == sorted(
        path.relative_to(second) for path in second.rglob("*") if path.is_file()
    )
    assert all(
        (first / path).read_bytes() == (second / path).read_bytes() for path in files
    )
    cases = [
        json.loads(line) for line in (first / "cases.jsonl").read_text().splitlines()
    ]
    assert len(cases) == 30
    assert sum(case["is_impossible"] for case in cases) == 10
    assert len({case["passage_id"] for case in cases}) == 10
    assert len(list((first / "corpus").glob("*.md"))) == 20
    assert sum(p["role"] == "extra" for p in manifest["passages"]) == 10
    original = {
        qa["id"]: qa
        for article in load_source(source)["data"]
        for paragraph in article["paragraphs"]
        for qa in paragraph["qas"]
    }
    for case in cases:
        assert case["answers"] == original[case["id"]]["answers"]
        assert "plausible_answers" not in case
        if case["is_impossible"]:
            assert case["review_status"] == "needs_review"
        corpus = (first / "corpus" / f"{case['passage_id']}.md").read_text()
        assert case["question"] not in corpus
        assert "answer_start" not in corpus


@pytest.mark.parametrize(
    "damage", ["json", "version", "duplicate", "offset", "schema", "insufficient"]
)
def test_invalid_input_fails_without_output(
    source: Path, tmp_path: Path, damage: str
) -> None:
    """Reject invalid or undersized data without publishing a partial dataset."""
    data = json.loads(source.read_text())
    if damage == "version":
        data["version"] = "1.1"
    elif damage == "duplicate":
        data["data"][0]["paragraphs"][0]["qas"][1]["id"] = "answer-0-0"
    elif damage == "offset":
        data["data"][0]["paragraphs"][0]["qas"][0]["answers"][0]["answer_start"] = 0
    elif damage == "schema":
        data["data"][0]["paragraphs"][0]["qas"][0]["is_impossible"] = "false"
    elif damage == "insufficient":
        data["data"] = data["data"][:1]
    source.write_text("{" if damage == "json" else json.dumps(data), encoding="utf-8")
    with pytest.raises((ValueError, TypeError)):
        prepare(source, tmp_path / "output")
    assert not (tmp_path / "output").exists()


def test_existing_output_protected(source: Path, tmp_path: Path) -> None:
    """Never replace existing outputs or manual review work."""
    output = tmp_path / "output"
    output.mkdir()
    with pytest.raises(FileExistsError):
        prepare(source, output)
    review = output / "review.txt"
    review.write_text("reviewed")
    with pytest.raises(FileExistsError):
        prepare(source, output)
    assert review.read_text() == "reviewed"


def test_download_cache_and_cleanup(
    source: Path, tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    """Download through a mock, then reuse validated cache without network."""
    transport = Mock(return_value=io.BytesIO(source.read_bytes()))
    monkeypatch.setattr("scripts.prepare_squad.urlopen", transport)
    cache = tmp_path / "cache" / "dev.json"
    assert download_source(cache) == cache
    assert download_source(cache) == cache
    assert transport.call_count == 1
    assert list(cache.parent.iterdir()) == [cache]


@pytest.mark.parametrize("failure", ["network", "invalid", "interrupted"])
def test_download_failure_cleanup(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch, failure: str
) -> None:
    """Do not publish bad downloads or leave temporary files on failure."""
    response = io.BytesIO(b"invalid")
    transport = (
        Mock(side_effect=OSError("network unavailable"))
        if failure == "network"
        else Mock(return_value=response)
    )
    if failure == "interrupted":
        response = Mock()
        response.__enter__ = Mock(return_value=response)
        response.__exit__ = Mock(return_value=False)
        response.read.side_effect = [b'{"version":', OSError("interrupted")]
        transport.return_value = response
    monkeypatch.setattr("scripts.prepare_squad.urlopen", transport)
    cache = tmp_path / "cache" / "dev.json"
    with pytest.raises((OSError, ValueError)):
        download_source(cache)
    assert list(cache.parent.iterdir()) == []


